var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code: y = d * 365.25, so 1 year = 365.25 * d
    // The patched code: y = d / 365.25, so 1 year = d / 365.25
    // So in the original, 1 year is about 365.25 days
    // In the patched, 1 year is about 1/365.25 days
    // We can test this by checking that 1 year is much larger than 1 day in the original
    // But in the patched version, 1 year is much smaller than 1 day
    // So we test: in the original, ms('1 year') > ms('1 day')
    // In the patched, ms('1 year') < ms('1 day')
    // So we assert the opposite of what the test above did
    assert(ms('1 year') > ms('1 day'), '1 year should be greater than 1 day in the original code');
  });
});

